<?php require_once 'includes/config.php'; require_login();$pdo=db();$id=(int)($_GET['id']??0);$u=user();$st=$pdo->prepare('SELECT o.*,u.name,u.email,u.phone FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=? AND o.user_id=?');$st->execute([$id,$u['id']]);$o=$st->fetch();if(!$o){http_response_code(404);exit('Invoice not found.');}$st=$pdo->prepare('SELECT oi.*,p.name FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$st->execute([$id]);$items=$st->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>Invoice #<?=$id?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f6f3fa}.invoice{max-width:900px;margin:40px auto;background:#fff;padding:45px;border-radius:20px}.purple{color:#6f42c1}@media print{.no-print{display:none!important}.invoice{margin:0;box-shadow:none}}</style></head><body><div class="invoice"><div class="d-flex justify-content-between"><div><h2 class="purple fw-bold">ShopNex</h2><p>Online Shopping Center</p></div><div class="text-end"><h4>INVOICE #<?=$id?></h4><div><?=e($o['created_at'])?></div></div></div><hr><div class="row"><div class="col"><strong>Bill to</strong><p><?=e($o['name'])?><br><?=e($o['email'])?><br><?=e($o['phone'])?></p></div><div class="col"><strong>Ship to</strong><p><?=nl2br(e($o['address_text']))?></p></div></div><table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['unit_price']*$i['quantity'])?></td></tr><?php endforeach;?></tbody></table><div class="ms-auto" style="max-width:300px"><div class="d-flex justify-content-between"><span>Subtotal</span><b><?=money($o['subtotal'])?></b></div><div class="d-flex justify-content-between"><span>Shipping</span><b><?=money($o['shipping'])?></b></div><div class="d-flex justify-content-between"><span>Discount</span><b>-<?=money($o['discount'])?></b></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total</strong><strong class="purple"><?=money($o['total'])?></strong></div></div><button class="btn btn-primary no-print mt-4" onclick="print()">Print / Save PDF</button></div></body></html>
